 "purpose_evidence": [
  {"claim": "U0082 is a full-time clerk in the PCP clinic, scheduled 08:00-17:00 on 2026-10-15, so the accesses fall inside the workday.", "sources": ["G1", "G2", "L1", "L2", "L3"]},
