  {"claim": "All accesses used LAB devices D0363 and D0163, and the action mix (A0335 read, A0048 query, A0248 create, A0265 update) is consistent with lab order processing.", "sources": ["G21", "G16", "G22", "L1", "L3", "L4", "L6"]},
  {"claim": "U0264 worked many other patients that day from LAB devices, consistent with routine workload rather than targeting P00591.", "sources": ["L8", "L20", "L29", "L36", "G11", "G12", "G13", "G20", "G21"]}
 ],
 "risk_indicators": [
